        let steps_dir = temp.path().join(".bivvy").join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(
            temp.path().join(".bivvy").join("config.yml"),
            "app_name: test",
        )
        .unwrap();
        fs::write(steps_dir.join("database.yaml"), "command: rails db:setup").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert_eq!(paths.split_steps.len(), 1);
    }

    #[test]
    fn split_steps_only_counts_as_project_config() {
        let temp = TempDir::new().unwrap();
        let steps_dir = temp.path().join(".bivvy").join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(steps_dir.join("database.yml"), "command: rails db:setup").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        // No config.yml, but split files exist
        assert!(paths.project.is_none());
        assert!(paths.has_project_config());
    }

    #[test]
    fn load_merged_config_loads_split_steps() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        let steps_dir = bivvy_dir.join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: SplitApp").unwrap();
        fs::write(
            steps_dir.join("database.yml"),
            r#"
command: "rails db:setup"
title: "Setup database"
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(config.app_name, Some("SplitApp".to_string()));
        assert!(config.steps.contains_key("database"));
        assert_eq!(
            config.steps["database"].execution.command,
            Some("rails db:setup".to_string())
        );
        assert_eq!(
            config.steps["database"].title,
            Some("Setup database".to_string())
        );
    }

    #[test]
    fn load_merged_config_loads_split_workflows() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        let workflows_dir = bivvy_dir.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();
        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
app_name: SplitApp
steps:
  deps:
    command: "yarn install"
  test:
    command: "yarn test"
"#,
        )
        .unwrap();
        fs::write(
            workflows_dir.join("ci.yml"),
            r#"
description: "CI pipeline"
steps: [deps, test]
settings:
  non_interactive: true
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert!(config.workflows.contains_key("ci"));
        assert_eq!(
            config.workflows["ci"].description,
            Some("CI pipeline".to_string())
        );
        assert_eq!(config.workflows["ci"].steps, vec!["deps", "test"]);
    }

    #[test]
    fn split_steps_override_inline_steps() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        let steps_dir = bivvy_dir.join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
steps:
  database:
    command: "rails db:setup"
    title: "Original title"
"#,
        )
        .unwrap();
        // Split file overrides the command
        fs::write(
            steps_dir.join("database.yml"),
            r#"
command: "rails db:prepare"
title: "Overridden title"
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(
            config.steps["database"].execution.command,
            Some("rails db:prepare".to_string())
        );
        assert_eq!(
            config.steps["database"].title,
            Some("Overridden title".to_string())
        );
    }

    #[test]
    fn local_overrides_override_split_files() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        let steps_dir = bivvy_dir.join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: Test").unwrap();
        fs::write(
            steps_dir.join("database.yml"),
            r#"
command: "rails db:setup"
title: "From split file"
"#,
        )
        .unwrap();
        // config.local.yml overrides the split file
        fs::write(
            bivvy_dir.join("config.local.yml"),
            r#"
steps:
  database:
    command: "rails db:prepare"
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(
            config.steps["database"].execution.command,
            Some("rails db:prepare".to_string())
        );
        // title from split file should be preserved (deep merge)
        assert_eq!(
            config.steps["database"].title,
            Some("From split file".to_string())
        );
    }

    #[test]
    fn split_steps_and_inline_steps_coexist() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        let steps_dir = bivvy_dir.join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
steps:
  deps:
    command: "yarn install"
"#,
        )
        .unwrap();
        fs::write(
            steps_dir.join("database.yml"),
            "command: \"rails db:setup\"",
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert!(config.steps.contains_key("deps"));
        assert!(config.steps.contains_key("database"));
    }

    #[test]
    fn split_files_work_without_config_yml() {
        let temp = TempDir::new().unwrap();
        let steps_dir = temp.path().join(".bivvy").join("steps");
        let workflows_dir = temp.path().join(".bivvy").join("workflows");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::create_dir_all(&workflows_dir).unwrap();
        fs::write(steps_dir.join("deps.yml"), "command: \"yarn install\"").unwrap();
        fs::write(workflows_dir.join("default.yml"), "steps: [deps]").unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert!(config.steps.contains_key("deps"));
        assert!(config.workflows.contains_key("default"));
    }

    #[test]
    fn empty_split_dirs_are_ignored() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(bivvy_dir.join("steps")).unwrap();
        fs::create_dir_all(bivvy_dir.join("workflows")).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: Test").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert!(paths.split_steps.is_empty());
        assert!(paths.split_workflows.is_empty());
        assert!(!paths.has_split_files());
    }

    #[test]
    fn split_files_sorted_for_deterministic_order() {
        let temp = TempDir::new().unwrap();
        let steps_dir = temp.path().join(".bivvy").join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(
            temp.path().join(".bivvy").join("config.yml"),
            "app_name: test",
        )
        .unwrap();
        fs::write(steps_dir.join("zebra.yml"), "command: echo z").unwrap();
        fs::write(steps_dir.join("alpha.yml"), "command: echo a").unwrap();
        fs::write(steps_dir.join("middle.yml"), "command: echo m").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        let names: Vec<&str> = paths
            .split_steps
            .iter()
            .filter_map(|p| p.file_stem().and_then(|s| s.to_str()))
            .collect();
        assert_eq!(names, vec!["alpha", "middle", "zebra"]);
    }

    #[test]
    fn split_step_with_full_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        let steps_dir = bivvy_dir.join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: Test").unwrap();
        fs::write(
            steps_dir.join("database.yml"),
            r#"
title: "Setup database"
command: "rails db:setup"
depends_on: [deps]
check:
  type: execution
  command: "rails db:version"
retry: 2
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        let step = &config.steps["database"];
        assert_eq!(step.title, Some("Setup database".to_string()));
        assert_eq!(step.execution.command, Some("rails db:setup".to_string()));
        assert_eq!(step.depends_on, vec!["deps"]);
        assert!(step.execution.check.is_some());
        assert_eq!(step.execution.retry, 2);
    }

    // --- Targeted loader tests (Phase 1) ---

    #[test]
    fn load_project_config_reads_only_project_file() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy).unwrap();
        fs::write(bivvy.join("config.yml"), "app_name: ProjectOnly").unwrap();

        // Local file that load_project_config should ignore
        fs::write(bivvy.join("config.local.yml"), "app_name: LocalOverride\n").unwrap();

        let config = load_project_config(temp.path()).unwrap();
        assert_eq!(config.app_name, Some("ProjectOnly".to_string()));
    }

    #[test]
    fn load_project_config_errors_when_missing() {
        let temp = TempDir::new().unwrap();
        let result = load_project_config(temp.path());
        assert!(matches!(result, Err(BivvyError::ConfigNotFound { .. })));
    }

    #[test]
    fn load_single_workflow_file_parses_legacy_format() {
        let temp = TempDir::new().unwrap();
        let workflows_dir = temp.path().join(".bivvy").join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();
        let path = workflows_dir.join("ci.yml");
        fs::write(
            &path,
            r#"
description: "CI pipeline"
steps: [deps, test]
"#,
        )
        .unwrap();

        let file = load_single_workflow_file(&path).unwrap();
        assert_eq!(file.description, Some("CI pipeline".to_string()));
        assert!(file.steps.is_empty());
        assert!(file.vars.is_empty());
        assert_eq!(file.workflow.steps, vec!["deps", "test"]);
    }

    #[test]
    fn load_single_workflow_file_parses_new_format() {
        let temp = TempDir::new().unwrap();
        let workflows_dir = temp.path().join(".bivvy").join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();
        let path = workflows_dir.join("release.yml");
        fs::write(
            &path,
            r#"
description: "Release prep"
steps:
  fetch:
    command: "git fetch"
vars:
  ver: "1.0"
workflow:
  steps:
    - fetch
"#,
        )
        .unwrap();

        let file = load_single_workflow_file(&path).unwrap();
        assert_eq!(file.description, Some("Release prep".to_string()));
        assert!(file.steps.contains_key("fetch"));
        assert!(file.vars.contains_key("ver"));
        assert_eq!(file.workflow.steps, vec!["fetch"]);
    }

    #[test]
    fn load_single_step_file_parses_step_yaml() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("step.yml");
        fs::write(
            &path,
            r#"
title: "Setup database"
command: "rails db:setup"
"#,
        )
        .unwrap();

        let step = load_single_step_file(&path).unwrap();
        assert_eq!(step.title, Some("Setup database".to_string()));
        assert_eq!(step.execution.command, Some("rails db:setup".to_string()));
    }

    #[test]
    fn load_for_run_only_loads_named_workflow_file() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(bivvy.join("config.yml"), "app_name: Test").unwrap();

        // The workflow we want to run.
        fs::write(
            workflows_dir.join("good.yml"),
            r#"
description: "Good workflow"
steps:
  hello:
    command: "echo hello"
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        // A malformed sibling — must not be parsed.
        fs::write(
            workflows_dir.join("broken.yml"),
            "this: is: not: valid: yaml: at all",
        )
        .unwrap();

        let config = load_for_run(temp.path(), "good").unwrap();
        assert!(config.workflows.contains_key("good"));
        assert!(!config.workflows.contains_key("broken"));
        assert!(config.steps.contains_key("hello"));
    }

    #[test]
    fn load_for_run_workflow_step_overrides_project_step() {
        // Resolution chain: project (3) → workflow file (5) → local (6).
        // Workflow files override project config; local overrides everything.
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(
            bivvy.join("config.yml"),
            r#"
app_name: Test
steps:
  hello:
    command: "from project"
"#,
        )
        .unwrap();

        fs::write(
            workflows_dir.join("greet.yml"),
            r#"
steps:
  hello:
    command: "from workflow file"
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "greet").unwrap();
        assert_eq!(
            config.steps["hello"].execution.command,
            Some("from workflow file".to_string())
        );
    }

    #[test]
    fn load_for_run_local_overrides_workflow_step() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(bivvy.join("config.yml"), "app_name: Test").unwrap();

        fs::write(
            workflows_dir.join("greet.yml"),
            r#"
steps:
  hello:
    command: "workflow"
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        fs::write(
            bivvy.join("config.local.yml"),
            r#"
steps:
  hello:
    command: "local override"
"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "greet").unwrap();
        assert_eq!(
            config.steps["hello"].execution.command,
            Some("local override".to_string())
        );
    }

    #[test]
    fn load_for_run_handles_legacy_workflow_layout() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(
            bivvy.join("config.yml"),
            r#"
app_name: Legacy
steps:
  deps:
    command: "yarn install"
"#,
        )
        .unwrap();

        fs::write(
            workflows_dir.join("ci.yml"),
            r#"
description: "Legacy CI"
steps: [deps]
"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "ci").unwrap();
        let workflow = config.workflows.get("ci").unwrap();
        assert_eq!(workflow.description, Some("Legacy CI".to_string()));
        assert_eq!(workflow.steps, vec!["deps"]);
        assert!(config.steps.contains_key("deps"));
    }

    #[test]
    fn load_merged_config_handles_new_format_workflow_files() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(bivvy.join("config.yml"), "app_name: Mixed").unwrap();

        fs::write(
            workflows_dir.join("release.yml"),
            r#"
description: "Release"
steps:
  fetch:
    command: "git fetch"
workflow:
  steps:
    - fetch
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        let workflow = config.workflows.get("release").unwrap();
        assert_eq!(workflow.description, Some("Release".to_string()));
        assert_eq!(workflow.steps, vec!["fetch"]);
        assert!(config.steps.contains_key("fetch"));
    }
}

