            workflows_dir.join("greet.yml"),
            r#"
description: "Greet the user"
steps:
  hello:
    command: echo hello
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        let args = RunArgs {
            workflow: "greet".to_string(),
