113	/// Validate step definitions.
114	fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
115	    let mut errors = Vec::new();
116	
117	    for (name, step) in &config.steps {
118	        // Step must have either template or command
119	        if step.template.is_none() && step.execution.command.is_none() {
120	            errors.push(ValidationError {
121	                rule: "missing-command".to_string(),
122	                message: format!("Step '{}' must have either 'template' or 'command'", name),
123	                step: Some(name.clone()),
124	                workflow: None,
125	            });
126	        }
127	
128	        // Validate depends_on references
129	        for dep in &step.depends_on {
130	            if !config.steps.contains_key(dep) {
131	                errors.push(ValidationError {
132	                    rule: "unknown-step".to_string(),
133	                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
134	                    step: Some(name.clone()),
135	                    workflow: None,
136	                });
137	            }
138	        }
139	    }
140	
